/**
 * Target File Size Optimizer
 *
 * Combines iterative compression quality/scaling search with safe format padding.
 * When the file exceeds maxBytes, it compresses quality and (optionally) dimensions.
 * When the file is below minBytes, it safely increases file size using format-compliant metadata.
 * Always measures and reports the exact generated byte size.
 */

import { renderToCanvas, canvasToBlob, SUPPORTED_FORMATS } from './imageProcessor';
import { formatBytes } from './units';
import { padBlobToFileSize } from './filePadders';

export async function optimizeToTargetSize({
  img,
  baseWidth,
  baseHeight,
  format = 'image/webp',
  minBytes,
  maxBytes,
  allowDimensionScaling = true,
  fitMode = 'contain',
  fillColor = '#FFFFFF',
  onProgress = () => {},
  shouldCancel = () => false,
}) {
  const isLossy = format === 'image/jpeg' || format === 'image/webp';
  let step = 0;
  let bestCandidate = null;
  const createdObjectUrls = [];

  const registerUrl = (url) => {
    createdObjectUrls.push(url);
    return url;
  };

  const cleanupNonBestUrls = (keepUrl) => {
    createdObjectUrls.forEach((url) => {
      if (url !== keepUrl) {
        URL.revokeObjectURL(url);
      }
    });
  };

  const evaluateCandidate = async (width, height, quality, stepDesc) => {
    step += 1;
    const clampedW = Math.max(1, Math.round(width));
    const clampedH = Math.max(1, Math.round(height));
    const clampedQ = isLossy ? Math.min(1.0, Math.max(0.05, quality)) : 1.0;

    const canvas = renderToCanvas(img, clampedW, clampedH, format, { fitMode, fillColor });
    const blob = await canvasToBlob(canvas, format, clampedQ);
    const objectUrl = registerUrl(URL.createObjectURL(blob));

    const inRange = blob.size >= minBytes && blob.size <= maxBytes;
    const distanceToRange = inRange
      ? 0
      : blob.size < minBytes
      ? minBytes - blob.size
      : blob.size - maxBytes;

    const candidate = {
      step,
      width: clampedW,
      height: clampedH,
      quality: clampedQ,
      size: blob.size,
      blob,
      objectUrl,
      inRange,
      distanceToRange,
      description: stepDesc,
    };

    if (!bestCandidate) {
      bestCandidate = candidate;
    } else if (candidate.inRange) {
      if (!bestCandidate.inRange || candidate.quality > bestCandidate.quality) {
        bestCandidate = candidate;
      }
    } else if (!bestCandidate.inRange && candidate.distanceToRange < bestCandidate.distanceToRange) {
      bestCandidate = candidate;
    }

    onProgress({
      step,
      candidate,
      bestCandidate,
      status: `Testing ${clampedW}×${clampedH}px @ ${Math.round(clampedQ * 100)}% (${formatBytes(blob.size)})`,
    });

    await new Promise((r) => setTimeout(r, 35));
    return candidate;
  };

  try {
    // -------------------------------------------------------------
    // Format Case 1: PNG (Lossless)
    // -------------------------------------------------------------
    if (!isLossy) {
      const initial = await evaluateCandidate(baseWidth, baseHeight, 1.0, 'Base PNG');
      if (shouldCancel()) {
        cleanupNonBestUrls(bestCandidate?.objectUrl);
        return { canceled: true, bestCandidate };
      }

      if (initial.inRange) {
        cleanupNonBestUrls(bestCandidate.objectUrl);
        return {
          success: true,
          bestCandidate,
          message: `Target reached: ${formatBytes(initial.size)} at native dimensions.`,
        };
      }

      // If scaling is allowed and size is too big, scale dimensions
      if (initial.size > maxBytes && allowDimensionScaling) {
        let minScale = 0.05;
        let maxScale = 1.0;
        let iter = 0;

        while (iter < 8 && !shouldCancel()) {
          iter++;
          const scale = (minScale + maxScale) / 2;
          const testW = Math.round(baseWidth * scale);
          const testH = Math.round(baseHeight * scale);
          if (testW < 10 || testH < 10) break;

          const candidate = await evaluateCandidate(testW, testH, 1.0, `Scaling to ${Math.round(scale * 100)}%`);
          if (candidate.inRange) {
            cleanupNonBestUrls(candidate.objectUrl);
            return {
              success: true,
              bestCandidate: candidate,
              message: `Target reached: scaled to ${testW}×${testH}px (${formatBytes(candidate.size)}).`,
            };
          }
          if (candidate.size > maxBytes) {
            maxScale = scale;
          } else {
            minScale = scale;
          }
        }
      }
    } else {
      // -------------------------------------------------------------
      // Format Case 2: Lossy (WebP or JPEG)
      // -------------------------------------------------------------
      let qLow = 0.05;
      let qHigh = 1.0;
      let qIterations = 0;

      // Check max quality first
      const maxQCandidate = await evaluateCandidate(baseWidth, baseHeight, 1.0, 'Max quality (100%)');
      if (shouldCancel()) {
        cleanupNonBestUrls(bestCandidate?.objectUrl);
        return { canceled: true, bestCandidate };
      }
      if (maxQCandidate.inRange) {
        cleanupNonBestUrls(maxQCandidate.objectUrl);
        return {
          success: true,
          bestCandidate: maxQCandidate,
          message: `Target reached at 100% quality: ${formatBytes(maxQCandidate.size)}.`,
        };
      }

      // Binary search quality at base dimensions
      while (qIterations < 8 && !shouldCancel()) {
        qIterations++;
        const testQ = (qLow + qHigh) / 2;
        const candidate = await evaluateCandidate(baseWidth, baseHeight, testQ, `Quality step ${qIterations}`);

        if (candidate.inRange) {
          cleanupNonBestUrls(candidate.objectUrl);
          return {
            success: true,
            bestCandidate: candidate,
            message: `Target reached: ${formatBytes(candidate.size)} @ ${Math.round(testQ * 100)}% quality.`,
          };
        }

        if (candidate.size > maxBytes) {
          qHigh = testQ;
        } else {
          qLow = testQ;
        }
      }

      // If still too large and dimension scaling allowed, scale down
      if (bestCandidate.size > maxBytes && allowDimensionScaling && !shouldCancel()) {
        const dimensionScales = [0.85, 0.7, 0.55, 0.4, 0.25, 0.15];
        for (const scale of dimensionScales) {
          if (shouldCancel()) break;
          const scaledW = Math.max(16, Math.round(baseWidth * scale));
          const scaledH = Math.max(16, Math.round(baseHeight * scale));

          let subQLow = 0.1;
          let subQHigh = 0.95;
          let subSteps = 0;

          while (subSteps < 5 && !shouldCancel()) {
            subSteps++;
            const midQ = (subQLow + subQHigh) / 2;
            const candidate = await evaluateCandidate(
              scaledW,
              scaledH,
              midQ,
              `Scaled to ${Math.round(scale * 100)}% @ ${Math.round(midQ * 100)}% Q`
            );

            if (candidate.inRange) {
              cleanupNonBestUrls(candidate.objectUrl);
              return {
                success: true,
                bestCandidate: candidate,
                message: `Target reached: ${formatBytes(candidate.size)} (${scaledW}×${scaledH}px @ ${Math.round(midQ * 100)}% Q).`,
              };
            }

            if (candidate.size > maxBytes) {
              subQHigh = midQ;
            } else {
              subQLow = midQ;
            }
          }
        }
      }
    }

    // -------------------------------------------------------------
    // AUTOMATIC FILE-SIZE INCREASE (SAFE PADDING)
    // If best candidate is smaller than minBytes, safely pad it
    // -------------------------------------------------------------
    if (bestCandidate && bestCandidate.size < minBytes && !shouldCancel()) {
      onProgress({
        step,
        bestCandidate,
        status: `File is smaller than minimum target (${formatBytes(bestCandidate.size)}). Applying safe padding...`,
      });

      // Target size in middle of [minBytes, maxBytes]
      const targetPadByteGoal = Math.round(minBytes + (maxBytes - minBytes) * 0.25);
      const neededPadding = targetPadByteGoal - bestCandidate.size;

      if (neededPadding > 0) {
        const padRes = await padBlobToFileSize(bestCandidate.blob, neededPadding);
        if (padRes.success && padRes.size >= minBytes && padRes.size <= maxBytes) {
          const paddedUrl = registerUrl(URL.createObjectURL(padRes.blob));
          bestCandidate = {
            ...bestCandidate,
            size: padRes.size,
            blob: padRes.blob,
            objectUrl: paddedUrl,
            inRange: true,
          };

          cleanupNonBestUrls(paddedUrl);
          return {
            success: true,
            bestCandidate,
            message: `Target reached: ${formatBytes(bestCandidate.size)} (safely increased file size to meet minimum requirement).`,
          };
        }
      }
    }

    cleanupNonBestUrls(bestCandidate?.objectUrl);
    const reachedTarget = bestCandidate && bestCandidate.inRange;

    let finalMessage = '';
    if (reachedTarget) {
      finalMessage = `Target reached: ${formatBytes(bestCandidate.size)}.`;
    } else if (bestCandidate.size > maxBytes) {
      finalMessage = `Could not reach target: smallest output is ${formatBytes(bestCandidate.size)} (ceiling: ${formatBytes(maxBytes)}).`;
    } else {
      finalMessage = `Could not reach target: largest output is ${formatBytes(bestCandidate.size)} (minimum: ${formatBytes(minBytes)}).`;
    }

    return {
      success: reachedTarget,
      bestCandidate,
      message: finalMessage,
    };
  } catch (err) {
    cleanupNonBestUrls(bestCandidate?.objectUrl);
    return {
      success: false,
      bestCandidate,
      error: err.message,
      message: `Search error: ${err.message}`,
    };
  }
}
